interactionHint.value:
{ $representationType ->
  [beads] 导航到并抓取珠子以创建组，或跨过分隔线改变颜色。
  [kittens] 选择小猫以移动、组织或改变其颜色。
  [numberLine] 移动加数分隔旋钮以改变黄色和蓝色段的长度。
  *[location] { a11y_introScreen_screenSummary_interactionHint }
}

objectResponse.value:
{ $grabbedOrReleased ->
  [grabbed] { $side ->
              [left] 已抓取，在分隔线左侧
              *[right] 已抓取，在分隔线右侧
            }
  *[released] { $side ->
                [left] 已释放，在分隔线左侧
                *[right] 已释放，在分隔线右侧
              }
}

accessibleParagraph.value:
{ $type ->
  [kittens] 此刻，计数区域中有 { $leftAddend } 只黄色小猫，{ $rightAddend } 只蓝色小猫。
  *[numberLine] { $visible ->
                  [none] { a11y_gameScreen_countingArea_numberLineSentence }
                  [addends] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends }
                  [tickMarks] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineTickMarks }
                  *[both] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends } { a11y_gameScreen_countingArea_numberLineTickMarks }
                }
}

correctAnswerOnFirstTry.value:
{ $levelType ->
  [sum] 你正确！{ $leftAddend } 加 { $rightAddend } 等于 { $total }。{ a11y_gameScreen_responses__correctAnswerScore }
  *[decomposition] 你正确！{ $total } 可以分成 { $leftAddend } 和 { $rightAddend }。{ a11y_gameScreen_responses__correctAnswerScore }
}
